#include "isr.h"
#include "adc_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

double adc_convert_min_max_avg (Adc_Channel adc_channel , UInt8 filter_size)
{
  UInt32 sum = 0 ;

  UInt16 adc_min = 0xFFFF ;
  UInt16 adc_max = 0x0000 ;

  if (filter_size < 3)
    {
      filter_size = 3 ;
    }

  os_res_request (adc_res , 0) ;
    {
      UInt8 n = 0 ;

      do
        {
          UInt16 adc_val = adc_convert_raw (adc_channel) ;

					if(adc_val == 0x3FF)
						continue;  // occasionally happens on LPC17xx, we did not find out why.

          sum += adc_val ;

               if (adc_val > adc_max) adc_max = adc_val ;
          else if (adc_val < adc_min) adc_min = adc_val ;
					
					n++;
        }
      while (n < filter_size) ;
    }
  os_res_release (adc_res) ;

  sum -= adc_min ;
  sum -= adc_max ;

  return sum / (double)(filter_size - 2) ;
}

